const puppeteer = require('puppeteer');

(async () => {
  const browser = await puppeteer.launch({
    headless: 'new',
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });
  const page = await browser.newPage();

  // Set viewport to the A0 size I styled in CSS
  await page.setViewport({ width: 2480, height: 3508, deviceScaleFactor: 1 });

  await page.goto('file:///app/output/poster.html', { waitUntil: 'networkidle0' });

  // Give it an extra second for AntV to fully animate/render
  await new Promise(r => setTimeout(r, 2000));

  await page.screenshot({ path: '/app/output/final_poster.png', fullPage: true });

  await browser.close();
})();
